import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易要义卷三 * 下","description":"周易要义 - 周易要义卷三 * 下","frontmatter":{"title":"周易要义卷三 * 下","description":"周易要义 - 周易要义卷三 * 下"},"headers":[],"relativePath":"zh/classics/yaoyi/008.md","filePath":"zh/classics/yaoyi/008.md"}'),r={name:"zh/classics/yaoyi/008.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易要义卷三-下" tabindex="-1">周易要义卷三 * 下 <a class="header-anchor" href="#周易要义卷三-下" aria-label="Permalink to “周易要义卷三 * 下”">​</a></h1><p>钦定四库全书</p><p>宋魏了翁辑大畜至离</p><p>䷙</p><p>乾下艮上 大畜：利贞。不家食，吉。利涉大川。正义曰：谓之「大畜」者，乾刚上进，艮止在上，止而畜之，能畜止刚健，故曰「大畜」。彖云「能止健，大正」也，是能止健，故为「大畜」也。小畜则巽在乾上，以其巽顺，不能畜止乾之刚，故云小畜也。此则艮能止之，故为「大畜」也。「利贞」者，人能止健，非正不可，故「利贞」也。「不家食，吉」者，己有大畜之资，当须养赡贤人，不使贤人在家自食，如此乃吉也。「利涉大川」者，丰财养贤，应于天道，不忧险难，故「利涉大川」。畜，本又作蓄，敕六反，义与小畜同。艮宫二世卦。</p><p>彖曰：大畜，刚健笃实，𪸩光日新其德。凡物既厌而退者，弱也；既荣而陨者，薄也。夫能「𪸩光日新其德」，唯「刚健笃实」也。</p><p>「大畜刚健」绝句，「笃实𪸩光」绝句。𪸩音辉。「日新其德」，郑以「日新」绝句，「其德」连下句。正义曰：言「大畜刚健笃实」者，此释大畜之义。「刚健」谓乾也，乾体刚性健，故言「刚健」也。「笃实」谓艮也，艮体静止，故称「笃实」也。𪸩光日新其德者，以其刚健笃实之故，故能辉耀光荣，日日增新其德。</p><p>象曰：天在山中，大畜。君子以多识前言往行，以畜其德。物之可畜于怀，令德不散，尽于此也。正义曰：「天在山中」者，欲取德积于身中，故云「天在山中」。</p><p>九三：良马逐，利艰贞。曰闲舆卫，利有攸往。凡物极则反，故畜极则通。初、二之进，值于畜盛，故不可以升。至于九三，升于上九，而上九处天衢之亨，涂径大通，进无违距，可以驰骋，故曰「良马逐」也。履当其位，进得其时，在乎通路，不忧险阨，故「利艰贞」也。闲，阂也。卫，护也。进得其时，虽涉艰难而无患也。舆虽遇闲而故卫也。与上合志，故「利有攸往」也。逐，如字，郑本作「逐逐」，云：「两马走也。」姚云：「逐逐，疾并驱之貌。」一音胄。曰，音越，刘云：「曰犹言也。」郑人寔反，云日习车徒。</p><p>上九：何天之衢，亨。处畜之极，畜极则通，大畜以至于大亨之时。何，辞也，犹云何畜乃天之衢，亨也。何，音河，梁武帝音贺。</p><p>䷚</p><p>震下艮上 颐。贞吉。观颐，自求口实。正义曰：「颐，贞吉」者，于颐养之世，养此贞正，则得吉也。「观颐」者，颐，养也，观此圣人所养物也。「自求口实」者，观其自养，求其口中之实也。颐以之反养也。此篆文字也。巽宫游魂卦。</p><p>象曰：山下至饮食。正义曰：山止于上，雷动于下。颐之为用，下动上止，故曰「山下有雷」。颐，人之开发言语，咀嚼饮食，皆动颐之事，故君子观此颐象，以谨慎言语，裁节饮食。先儒云：祸从口出，患从口入，故于颐养而慎节也。</p><p>初九，舍尔灵龟，观我朵颐，凶。朵颐者，嚼也。以阳处下而为动始，不能令物由己养动而求养者也。夫安身莫若不竞，修己莫若自保。守道则福至，求禄则辱来。居养贤之世，不能贞其所履，以全其德，而舍其灵龟之明兆，羡我朵颐而躁求，离其致养之至道，𬮭我宠禄而竞进，凶莫甚焉。象曰：观我朵颐，亦不足贵也。正义曰：「朵颐者，嚼也」者，朵是动义，如手之捉物谓之朵也。今动其颐，故知嚼也。「不能令物由已养」者，若道德弘大，则已能养物，是物由已养。今身处无位之地，又居震动之始，是动而自求养也。</p><p>六二，颠颐，拂经于丘颐，征凶。养下曰颠。拂，违也。经犹义也。丘，所履之常也。处下体之中，无应于上，反而养初，居下不奉上而反养下，故曰「颠颐，拂经于丘」也。以此而养，未见其福也；以此而行，未见有与，故曰「颐，征凶」。</p><p>六四，颠颐，吉。虎视耽耽，其欲逐逐，无咎。颐属上体，居得其位，而应于初，以上养下，得颐之义，故曰「颠颐，吉」也。下交不可以渎，故虎视耽耽，威而不猛，不恶而严，养德施贤，何可有利？故其欲逐逐，尚敦实也。修此二者，然后乃得全其吉而「无咎」。观其自养则履正，察其所养则养阳，颐爻之贵，斯为盛矣。视，徐市志反，又常止反。眈，丁南反，威而不猛也。马云：虎下视貌。</p><p>上九，由颐至有庆也。正义曰：「由颐」者，以阳处上而履四阴，阴不能独为其主，必宗事于阳也。众阴莫不由之以得其养，故曰「由颐」也。「厉，吉」者，为众阴之主，不可亵渎，严厉乃吉。</p><p>䷛</p><p>巽下兑上 大过，音相过之过，徐并古卧反，罪过也，超过也。王肃音戈，震宫游魂卦。</p><p>正义曰：「过」谓过越之过，非经过之过。此衰难之世，唯阳爻乃大能过越常理，以拯患难也，故曰「大过」。以人事言之，犹若圣人过越常理，以拯患难也。「栋桡」者，谓屋栋也。本之与末俱桡弱，以言衰乱之世，始终皆弱也。「利有攸往，亨」者，既遭衰难，圣人利有所往以拯患难，乃得亨通。</p><p>象曰：泽灭至无闷。正义曰：「泽灭木」者，泽体处下，木体处上，泽无灭木之理。今云「泽灭木」者，乃是泽之甚极而至灭木，是极大过越之义。其大过之卦有二义也：一者物之自然大相过越常分，即此「泽灭木」是也；二者大人大过越常分以拯患难，则九二「枯杨生稊，老夫得其女妻」是也。「君子以独立不惧，遁世无闷」者，明君子于衰难之时，卓尔独立，不有畏惧，隐遁于世而无忧闷，欲有遁难之心，其操不改。凡人遇此则不能然，唯君子独能如此，是其过越之义。遁，本又作遁。</p><p>以阳处阴，能过其本而救其弱者也。上无其应，心无特吝，处过以此，无衰不济也。故能令枯杨更生稊，老夫更得少妻，拯弱兴衰，莫盛斯爻，故「无不利」也。老过则枯，少过则稚。以老分少，则稚者长；以稚分老，则枯者荣。过以相与之谓也。大过至衰而已至壮，以至壮辅至衰，应斯义也。</p><p>九四，栋隆至乎下也。正义曰：「栋隆，吉」者，体居上体，以阳处阴，能拯救其弱，不为下所桡，故得栋隆起而𫉬吉也。「有它吝」者，以有应在初，心不弘阔，故「有它吝」也。象曰：「栋隆」之吉，不桡乎下也者，释「栋隆之吉」。以其能拯于难，不被桡乎在下，故得「栋隆，吉」。九四应初，行又谦顺，能拯于难，然唯只拯初，初谓下也。下得其拯，犹若所居屋栋隆起，下必不桡弱，何得云「不被桡乎在下」？但经文云「栋桡」，彖释「栋桡」者，本末弱也。以屋栋桡弱而偏，则屋下榱柱亦先弱。柱为本，榱为末，观此彖辞，是已见其义。故子产云：「栋折榱崩，侨将压焉。」以屋栋桡折，则榱柱亦同崩，则此义也。</p><p>上六，过涉灭顶，凶，无咎。处大过之极，过之甚也。涉难过甚，故至于灭顶，凶。志在救时，故不可咎也。顶，徐都冷反。象曰：「过涉」之凶，不可咎也。虽凶无咎，不害义也。正义曰：犹龙逢、比干忧时危乱，不惧诛杀，直言深谏，以忤无道之主，遂至灭亡。其意则善而功不成，复有何咎责。</p><p>䷜</p><p>坎下坎上， 习坎。坎，险陷之名也。习谓便习之习。便，习也，重也。刘云：「水流行不休，故曰习坎。」徐苦感反，本亦作掐。京、刘作「欿」。险也，陷也。八纯卦，象水陷陷没之陷。便，婢面反，通见后。</p><p>有孚，维心亨。刚正在内，「有孚」者也。阳不外发，而在乎内，「心亨」者也。行有尚。内亨外暗，内刚外顺，以此行险，「行有尚」也。正义曰：心亨，言心得通也。「行有尚」者，内亨外暗，内刚外柔，以此行险，事事可上，故云「行有尚」也。案：诸卦之名，皆于卦上不加其字。此坎卦之名特加「习」者，以坎为险难，故特加「习」名。「习」有二义：一者，习，重也，谓上下俱坎，是重叠有险，险之重叠，乃成险之用也。二者，人之行险，先须便习其事，乃可得通。</p><p>六三来之坎坎，险且枕，入于坎窞，勿用。既履非其位，而又处两坎之间，出则之坎，居则亦坎，故曰「来之坎坎」也。枕者，枕枝而不安之谓也，出则无之，处则无安，故曰「险且枕」也。来之皆坎，无所用之，徒劳而已。险且，如字，古文及郑、向本作检，郑云：「木在手曰检。」枕，徐针鸩反，王肃针甚反，郑玄云：「木在首曰枕。」</p><p>六四樽酒簋贰用缶，纳约自牖，终无咎。处重险而履正，以柔居柔，履得其位，以承于五，五亦得位，刚柔各得其所，不相犯位，皆无余应以相承比，明信显著，不存外饰。处坎以斯，虽复一樽之酒，二簋之食，瓦缶之器，纳此至约，自进于牖，乃可羞之于王公，荐之于宗庙，故「终无咎」也。樽酒，音尊，绝句。簋贰音轨，绝句。用缶，方有反，绝句。旧读「樽酒簋」绝句，「贰用缶」一句。象曰：「樽酒簋贰」，刚柔际也。刚柔相比而相亲焉，际之谓也。正义曰：所以一樽之酒，贰簋之食得进献者，以六四之柔与九五之刚，两相交际而相亲，故得以此俭约而为礼也。</p><p>九五，坎不盈，祗既平，无咎。为坎之主，而无应辅可以自佐，未能盈坎者也。坎之不盈，则险不尽矣。祗，辞也。为坎之主，尽平乃无咎，故曰「祗既平，无咎」也。说既平，乃无咎，明九五未免于咎也。祗，音支，又祁支反。郑云：「当为坻，小丘也。」</p><p>䷝</p><p>离下离上 离利贞，亨。离之为卦，以柔为正，故必贞而后乃亨，故曰「利贞，亨」也。畜牝牛，吉。柔处于内而履正中，牝之善也。外强而内顺，牛之善也。离之为体，以柔顺为主者也，故不可以畜刚猛之物，而「吉」于「畜牝牛」也。</p><p>正义曰：「柔处于内而履正中，牝之善也」者，若柔不处于内，似妇人而预外事；若柔而不履正中，则邪僻之行，皆非牝之善也。</p><p>又总释「畜牝牛吉」也。「柔丽于中正」，谓六五、六二之柔皆丽于中，中则不偏，故云中正。以中正为德，故万事亨。以中正得通，故畜养牝牛而得吉也，以牝牛有中正故也。案：诸卦之彖释卦名之下，乃释卦下之义，于后乃叹而美之。此彖既释卦名，即广叹为卦之美，乃释卦下之义。与诸卦不例者，此乃夫子随义则言，因文之便。此既释离名丽，因广说日月草木所丽之事，然后却明卦下之义，更无义例。</p><p>象曰：明两，至于四方。正义曰：「明两作，离」者，离为日，日为明，今有上下二离，故云「明两作，离」也。案：八纯之卦，论象不同，各因卦体事义随文而发。乾坤不论上下之体，直总云「天行健」，「地𫝑坤」，以天地之大，故总称上下二体也。雷是连续之至，水为流注不已，义皆取连续相因，故震云「瀳雷」，坎云「瀳至」也；风是摇动相随之物，故云「随风，巽」也。山泽各自为体，非相入之物，故云「兼山，艮」、丽泽，兑，是两物各行也。今明之为体，前后各照，故云「明两作离」，是积聚两明，乃作于离。若一明暂绝，其离未久，必聚两明，前后相续，乃得作离卦之美，故云「大人以继明照于四方」，是继续其明，乃得照于四方。若明不继续，则不得久为照临，所以特云「明两作离」，取不绝之义也。作，郑云：「作，起也。」荀云：「用也。」</p><p>六二：黄离，元吉。居中得位，以柔处柔，履文明之盛，而得其中，故曰「黄离，元吉」也。正义曰：黄者，中色也。离者，文明。居中得位，而处于文明，故「元吉」也。故象云「得中道」，以其得中央黄色之道也。</p><p>六五：出涕沱若、戚嗟若，吉。履非其位，不胜所履，以柔乘刚，不能制下，下刚而进，将来害己，忧伤之深，至于沱嗟也。然所丽在尊，四为逆首，忧伤至深，众之所助，故乃沱嗟而𫉬吉也。出，如字，徐尺遂反，王嗣宗𠡠类反。</p><p>正义：象曰「六五之吉，离王公」者，此释六五「吉」义也。所以终得吉者，以其所居在五，离附于王公之位，被众所助，故得吉也。五为王位，而言公者，此连王而言公，取其便文以会韵也。离王公，音丽，郑作丽。王肃云：「丽，王者之后为公。」梁武力智反。周易要义卷三下</p>',38)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
